/*
z = y
                    f(x) = x + z where x: ℝ
                    where
                    y: ℝ : a scalar
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT z;

    template<typename REAL>
    REAL f(
        const REAL & x)
    {
        return x + this->z;    
    }
    heartlib(const double & y)
    {

        // z = y
        z = y;
    }
};

