outputs.matlab:
function output = heartlib(y)
% output = heartlib(y)
%
%    z = y
%                        f(x) = x + z where x: ℝ
%                        where
%                        y: ℝ : a scalar
    assert(numel(y) == 1);

    % z = y

    z = y;
    function [ret] = f(x)
        assert(numel(x) == 1);

        ret = x + z;
    end

    output.z = z;
    output.f = @f;
end

